public int[]  have(int[] have_num, int soeji2) {//持ち駒を保存する処理
  if (soeji2 != 0) {
    if ( soeji2 >= 1 && soeji2 <= 7 ) {
      soeji2 = soeji2 - 1;
    } else if (soeji2 >= 8 && soeji2 <= 11) {
      soeji2 = soeji2 -8;
    } else {
      soeji2 = soeji2 - 7;
    }
    have_num[soeji2]++;
  }
  return have_num;
}

public int [] chessHave(int[] have_num, int soeji2) {
  if (soeji2 != 0) {
    soeji2 -= 1;
    have_num[soeji2]++;
  }
  return have_num;
}

public int viewHaveCheck() {
  float checkX, checkY;

  checkX = stage_x + box_size*10.5f;//下側の左
  checkY = stage_y + box_size*6;
  if (mouseX >= checkX && mouseX<= checkX+40 && mouseY >= checkY && mouseY <= checkY + 160) {  
    return 1;
  }

  checkX = checkX + box_size*1.5f;//下側の右
  //checkYは変わらない
  if (mouseX >= checkX && mouseX<= checkX+40 && mouseY >= checkY && mouseY <= checkY + 120) {
    return 2;
  }

  checkX = stage_x + box_size*(-4);//上側の左
  checkY = stage_y + 40;
  if (mouseX >= checkX && mouseX<= checkX+40 && mouseY >= checkY && mouseY <= checkY + 160) {
    return 3;
  }

  checkX = checkX + box_size*1.5f;//上側の右
  //checkYは変わらない
  if (mouseX >= checkX && mouseX<= checkX+40 && mouseY >= checkY && mouseY <= checkY + 120) {
    return 4;
  }
  return 0;//範囲内にマウスがなかったら0が返される
}

