public void viewHaveRect(int num) {
  float checkX, checkY;
  switch(num) {
  case 1://下側の左
    checkX = stage_x + box_size*10.5f;//下側の左
    checkY = stage_y + box_size*6;
    break;

  case 2://下側の右
    checkX = stage_x + box_size*12;//下側の右
    checkY = stage_y + box_size*6;
    break;

  case 3://上側の左
    checkX = stage_x + box_size*(-4);//上側の左
    checkY = stage_y + 40;
    break;

  case 4://上側の右
    checkX = stage_x + box_size*(-2.5f);//上側の右
    checkY = stage_y + 40;
    break;

  default://ここを通ることは絶対にない
    checkX =0;
    checkY = 0;
    break;
  }
  if (num == 1 || num == 3) {//上でも下で左側の時の処理
    for (int n = 0; n < 4; n++) {
      int j = 3 - n;
      if (mouseY >= checkY + j*40) {
        fill(0, 0, 255, 64);
        if (!(haveChoose)) {
          rect(checkX, checkY + j*40, 40, 40);
        }
        haveOption = j;//現在マウスがいる位置の駒の種類を保存
        break;
      }
    }
  } else {//右側の時の処理
    for (int n = 0; n < 3; n++) {
      int j = 2 - n;
      if (mouseY >= checkY + j*40) {
        fill(0, 0, 255, 64);
        if (!(haveChoose)) {
          rect(checkX, checkY + j*40, 40, 40);
        }
        haveOption = j + 4;//現在マウスがいる位置の駒の種類を保存
        break;
      }
    }
  }
}
