public void moveView(int y, int x) {
  int soeji[];
  soeji = bunnkai(stage_piece_num[y][x]);
  int viewCanMove[][];//ここにはどのマスに動けるかが入る
  int remit;
  remit = 32;
  fill(0, 255, 0, 64);
  rect(stage_x + box_size*x, stage_y + box_size*y, box_size, box_size);
  if ( soeji[0] == 1) {//下側陣営のとき
    viewCanMove = downCanMove[y][x];
  } else {
    viewCanMove = upCanMove[y][x];
  }
  int c = 0;
  fill(0xFFFF0000, 80);

  while (viewCanMove[c][0] != -1 ) {
    int v_y, v_x;
    v_y = viewCanMove[c][0];
    v_x = viewCanMove[c][1];
    rect(stage_x + box_size*v_x, stage_y + box_size*v_y, box_size, box_size);

    c += 1;
    if ( c >= remit) {
      break;
    }
  }
}

public boolean canPutCheck(int y, int x) {//マウスが動けるマスにあったら黄色になるようにする
  boolean canMove;//
  int soeji[];
  soeji = bunnkai(stage_piece_num[y][x]);
  int viewCanMove[][];//ここにはどのマスに動けるかが入る
  int remit;
  remit = 32;
  if ( soeji[0] == 1) {//下側陣営のとき
    viewCanMove = downCanMove[y][x];
  } else {
    viewCanMove = upCanMove[y][x];
  }

  /*ここからは駒を動けるようにする処理を書く*/
  canMove = false;
  if ((mouseX>= stage_x && mouseX < stage_x+stage_size) &&(mouseY >= stage_y && mouseY < stage_y + stage_size)) {//マウスが盤上にあったら処理をする
    int mouse_x = (((mouseX-6) - PApplet.parseInt(stage_x))/ (PApplet.parseInt(stage_size)/9));//盤上の座標
    int mouse_y = (((mouseY-6) - PApplet.parseInt(stage_y))/ (PApplet.parseInt(stage_size)/9));
    int d = 0;//カウント用の変数
    while (viewCanMove[d][0] != -1) {
      if (viewCanMove[d][0] == mouse_y && viewCanMove[d][1] == mouse_x) {
        fill(0, 255, 0, 80);//駒がある位置を黄色にする
        rect(stage_x + box_size*mouse_x, stage_y + box_size*mouse_y, box_size, box_size);
        canMove = true;
        break;
      }


      d += 1;
      if ( d >= remit) {
        break;
      }
    }
  }
  return canMove;
}

public void haveMoveView(float haveX, float haveY, int num, int option) {
  float checkX, checkY;
  switch(num) {
  case 1://下側の左
    checkX = stage_x + box_size*10.5f;//下側の左
    checkY = stage_y + box_size*6;
    break;

  case 2://下側の右
    checkX = stage_x + box_size*12;//下側の右
    checkY = stage_y + box_size*6;
    break;

  case 3://上側の左
    checkX = stage_x + box_size*(-4);//上側の左
    checkY = stage_y + 40;
    break;

  case 4://上側の右
    checkX = stage_x + box_size*(-2.5f);//上側の右
    checkY = stage_y + 40;
    break;

  default://ここを通ることは絶対にない
    checkX =0;
    checkY = 0;
    break;
  }
  if (num == 1 || num == 3) {//上でも下で左側の時の処理
    for (int n = 0; n < 4; n++) {
      int j = 3 - n;
      if (haveY >= checkY + j*40) {
        fill(0, 255, 0, 64);
        rect(checkX, checkY + j*40, 40, 40);

        break;
      }
    }
  } else {//右側の時の処理
    for (int n = 0; n < 3; n++) {
      int j = 2 - n;
      if (haveY >= checkY + j*40) {
        fill(0, 255, 0, 64);
        rect(checkX, checkY + j*40, 40, 40);

        break;
      }
    }
  }

  boolean haveCanPut[][] = new boolean[9][9];
  if (num <= 2) {//下側陣営
    if (option == 0) {//歩兵だったら
      haveCanPut = downHuhyoCanPut;
    } else if (option == 1) {//香車だったら
      haveCanPut = downKyosyaCanPut;
    } else if (option == 2) {//桂馬だったら
      haveCanPut = downKeimaCanPut;
    } else {//それ以外の駒だったら
      haveCanPut = normalCanPut;
    }
  } else {//上側陣営
    if (option == 0) {//歩兵だったら
      haveCanPut = upHuhyoCanPut;
    } else if (option == 1) {//香車だったら
      haveCanPut = upKyosyaCanPut;
    } else if (option == 2) {//桂馬だったら
      haveCanPut = upKeimaCanPut;
    } else {//それ以外の駒だったら
      haveCanPut = normalCanPut;
    }
  }
  canPuts = haveCanPut;//グローバル変数に保存
  fill(255, 0, 0, 80);//赤色に塗る
  for (int n = 0; n < haveCanPut.length; n++) {
    for (int j = 0; j < haveCanPut.length; j++) {
      if (haveCanPut[n][j]) {
        rect(stage_x + box_size*j, stage_y + box_size*n, box_size, box_size);//マウスがある位置を塗る
      }
    }
  }
}
public void haveChessMoveView(float haveX, float haveY, int num, int option) {
  float checkX, checkY;
  switch(num) {
  case 5://下側の左
    checkX = stage_x + box_size*10.5f;//下側の左
    checkY = stage_y + box_size*6 - 180;
    break;

  case 6://下側の右
    checkX = stage_x + box_size*12;//下側の右
    checkY = stage_y + box_size*6 - 180;
    break;

  case 7://上側の左
    checkX = stage_x + box_size*(-4);//上側の左
    checkY = stage_y + 260;
    break;

  case 8://上側の右
    checkX = stage_x + box_size*(-2.5f);//上側の右
    checkY = stage_y + 260;
    break;

  default://ここを通ることは絶対にない
    checkX =0;
    checkY = 0;
    break;
  }
  if (num == 5 || num == 7) {//上でも下で左側の時の処理
    for (int n = 0; n < 3; n++) {
      int j = 2 - n;
      if (haveY >= checkY + j*40) {
        fill(0, 255, 0, 64);
        rect(checkX, checkY + j*40, 40, 40);

        break;
      }
    }
  } else {//右側の時の処理
    for (int n = 0; n < 2; n++) {
      int j = 1 - n;
      if (haveY >= checkY + j*40) {
        fill(0, 255, 0, 64);
        rect(checkX, checkY + j*40, 40, 40);

        break;
      }
    }
  }

  boolean haveCanPut[][] = new boolean[9][9];
  if (num <= 6) {//下側陣営
    if (option == 0) {//ポーンだったら
      haveCanPut = downKyosyaCanPut;
    } else {//それ以外の駒だったら
      haveCanPut = normalCanPut;
    }
  } else {//上側陣営
    if (option == 0) {//歩兵だったら
      haveCanPut = upKyosyaCanPut;
    } else {//それ以外の駒だったら
      haveCanPut = normalCanPut;
    }
  }
  canPuts = haveCanPut;//グローバル変数に保存
  fill(255, 0, 0, 80);//赤色に塗る
  for (int n = 0; n < haveCanPut.length; n++) {
    for (int j = 0; j < haveCanPut.length; j++) {
      if (haveCanPut[n][j]) {
        rect(stage_x + box_size*j, stage_y + box_size*n, box_size, box_size);//マウスがある位置を塗る
      }
    }
  }
}

public void viewCheck() {
  fill(255);
  textSize(30);
  text("王手中です", width-consoleSize + 20, height/2+50);
}


